def parse_amount(text):
    # Strip whitespace
    text = text.strip()

    # Reject empty
    if not text:
        raise ValueError("Empty input")

    # Normalize comma to dot for decimal separator
    normalized = text.replace(',', '.')

    # Try to parse as float
    try:
        value = float(normalized)
    except ValueError:
        raise ValueError(f"Cannot parse '{text}' as a number")

    # Reject nan (nan != nan)
    if value != value:
        raise ValueError(f"Non-finite value not allowed: {text}")

    # Reject inf (check if value is extremely large)
    if abs(value) > 1e308:
        raise ValueError(f"Non-finite value not allowed: {text}")

    # Reject negative
    if value < 0:
        raise ValueError(f"Negative value not allowed: {text}")

    return value
